// غرفة قيادة الفرع البنكي - نموذج أولي مستقل للاستيراد في n8n
// مهم: لا توجد اتصالات خارجية في هذا الإصدار. القيم التشغيلية التجريبية موسومة بوضوح.
// عدّل قسم CONFIG بعد الاستيراد، ثم اربط مصادر بيانات معتمدة قبل الاعتماد على النتائج.

const CONFIG = {
  branchName: "فرع تجريبي - عدّل اسم الفرع",
  currency: "EGP",
  dataStatus: "DEMO_ONLY",
  targets: {
    customerWaitingMinutes: 10,
    dailySalesPerEmployeeEGP: 116000
  },
  // قيم توضيحية فقط وليست قراءة فعلية من أنظمة البنك
  demoActuals: {
    customerWaitingMinutes: 80,
    dailySalesEGP: 348000,
    dailySalesTargetEGP: 580000,
    customersServed: 42,
    pendingCases: 12
  },
  staff: {
    customerService: [
      { name: "كريستين", role: "خدمة عملاء", status: "غير محدد" },
      { name: "مارينا", role: "خدمة عملاء", status: "غير محدد" },
      { name: "منة الله", role: "خدمة عملاء", status: "غير محدد" },
      { name: "مروان", role: "خدمة عملاء", status: "غير محدد" }
    ],
    tellers: [
      { name: "محمد عبد السلام", role: "صراف", status: "غير محدد" },
      { name: "عبد الرحمن", role: "صراف", status: "غير محدد" },
      { name: "إشراق", role: "صراف", status: "غير محدد" },
      { name: "مينا", role: "صراف", status: "غير محدد" },
      { name: "نوران", role: "صراف", status: "غير محدد" }
    ],
    reception: [
      { name: "سارة", role: "استقبال / سفير رقمي", status: "غير محدد" }
    ],
    corporate: [
      { name: "كلارا", role: "خدمة الشركات", status: "غير محدد" }
    ],
    coordination: [
      { name: "هيلانة", role: "منسق أعمال", status: "غير محدد" }
    ]
  }
};

const a = CONFIG.demoActuals;
const salesAchievementPct = a.dailySalesTargetEGP > 0
  ? Math.round((a.dailySalesEGP / a.dailySalesTargetEGP) * 10000) / 100
  : 0;
const allStaff = [
  ...CONFIG.staff.customerService,
  ...CONFIG.staff.tellers,
  ...CONFIG.staff.reception,
  ...CONFIG.staff.corporate,
  ...CONFIG.staff.coordination
];

return [{
  json: {
    dashboard: "Ahmed Garad AI - Branch Command Center",
    branchName: CONFIG.branchName,
    generatedAt: new Date().toISOString(),
    dataStatus: CONFIG.dataStatus,
    warning: "هذه نتيجة نموذجية للتجربة فقط؛ لا توجد قراءة مباشرة من البنك أو Google Sheets.",
    currency: CONFIG.currency,
    kpis: {
      customerWaitingMinutes: {
        value: a.customerWaitingMinutes,
        target: CONFIG.targets.customerWaitingMinutes,
        status: a.customerWaitingMinutes <= CONFIG.targets.customerWaitingMinutes ? "on_target" : "above_target",
        unit: "minutes",
        dataStatus: CONFIG.dataStatus
      },
      dailySales: {
        actual: a.dailySalesEGP,
        target: a.dailySalesTargetEGP,
        achievementPercent: salesAchievementPct,
        remainingToTarget: Math.max(0, a.dailySalesTargetEGP - a.dailySalesEGP),
        currency: CONFIG.currency,
        dataStatus: CONFIG.dataStatus
      },
      customersServed: { value: a.customersServed, dataStatus: CONFIG.dataStatus },
      pendingCases: { value: a.pendingCases, dataStatus: CONFIG.dataStatus },
      staffCount: allStaff.length
    },
    teams: CONFIG.staff,
    staffRoster: allStaff,
    nextSteps: [
      "استبدل demoActuals ببيانات معتمدة من مصدر البنك أو ملف تجريبي تملكه.",
      "اربط Google Sheets أو مصدر البيانات المناسب باستخدام بيانات اعتماد تُنشأ داخل n8n؛ لا تضع مفاتيح API داخل الكود.",
      "اختبر كل مصدر ومخرجاته قبل تفعيل أي تشغيل مجدول.",
      "لا تستخدم هذا النموذج لاتخاذ قرارات ائتمانية أو تشغيلية فعلية قبل التحقق والموافقة."
    ]
  }
}];
